const image=/^(?:assets\/[A-Za-z0-9_./-]+\.(?:png|webp|jpe?g)|data:image\/(?:png|jpeg|webp);base64,[A-Za-z0-9+/=]+)$/;
function validate(input){if(!input||!Array.isArray(input.upserts)||!Array.isArray(input.hiddenIds)||input.upserts.length>100||input.hiddenIds.length>100)throw Error('Invalid pack update');const ids=new Set();const upserts=input.upserts.map(p=>{if(!/^[A-Z0-9-]{3,32}$/.test(p.id)||ids.has(p.id)||!/^[-a-z0-9]{3,80}$/.test(p.slug)||typeof p.name!=='string'||!p.name||p.name.length>100||typeof p.theme!=='string'||p.theme.length>80||!Number.isInteger(p.count)||p.count<1||p.count>100||typeof p.layout!=='string'||p.layout.length>100||typeof p.description!=='string'||p.description.length>2500||typeof p.image!=='string'||p.image.length>400000||!image.test(p.image)||p.image.includes('..')||!Array.isArray(p.code_list)||p.code_list.length>100||p.code_list.some(x=>!/^[A-Z0-9-]{3,24}$/.test(x))||new Set(p.code_list).size!==p.code_list.length)throw Error('Invalid pack details');if(p.code_list.length&&p.code_list.length!==p.count)throw Error('Pack count must match the selected catalogue codes');ids.add(p.id);return{id:p.id,slug:p.slug,name:p.name,theme:p.theme,count:p.count,layout:p.layout,description:p.description,image:p.image,code_list:p.code_list,codes:p.code_list.length?p.code_list.join(', '):p.count+' designs',kind:p.kind==='long'?'long':'sheet'};});const hiddenIds=[...new Set(input.hiddenIds)];if(hiddenIds.some(id=>!/^[A-Z0-9-]{3,32}$/.test(id)))throw Error('Invalid hidden pack');return{upserts,hiddenIds};}
module.exports={validate};

