/* Sticker Pack Hub — additive, preserving the original site */
.sticker-pack-hub{padding:76px max(22px,4vw);background:#f6f1e7;border-block:1px solid rgba(20,20,20,.12)}
.sticker-pack-head{display:flex;justify-content:space-between;gap:24px;align-items:end;margin-bottom:26px}.sticker-pack-head h2{font-size:clamp(2rem,5vw,5rem);line-height:.92;margin:.25rem 0}.sticker-pack-head p{max-width:720px}.pack-controls{display:flex;gap:8px}.pack-controls button{width:46px;height:46px;border:1px solid #111;background:#fff;border-radius:50%;font-size:1.25rem;cursor:pointer}
.pack-track{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(300px,410px);gap:18px;overflow:auto;scroll-snap-type:x mandatory;padding:4px 0 18px;scrollbar-width:thin}.pack-slide{scroll-snap-align:start;background:#fff;border:1px solid rgba(0,0,0,.14);border-radius:24px;overflow:hidden;box-shadow:0 10px 30px rgba(0,0,0,.06)}
.pack-visual{position:relative;aspect-ratio:4/3;background:#fff;overflow:hidden}.pack-visual>img{width:100%;height:100%;object-fit:contain;display:block}.pack-swap{position:absolute;right:12px;bottom:12px;background:#111;color:#fff;border:0;border-radius:999px;padding:10px 14px;font-weight:700;cursor:pointer}.pack-copy{padding:18px}.pack-copy h3{font-size:1.45rem;margin:.25rem 0 .45rem}.pack-prices{display:grid;grid-template-columns:auto 1fr auto 1fr;align-items:baseline;gap:4px 7px;margin:14px 0}.pack-prices b,.pack-prices i{font-size:1.55rem;font-style:normal}.pack-prices i{color:#7a2d75}.pack-prices span{font-size:.78rem;text-transform:uppercase;letter-spacing:.08em;color:#666}.pack-actions{display:flex;gap:8px;flex-wrap:wrap}.pack-actions button,.pack-actions a{border:1px solid #111;background:#111;color:#fff;border-radius:999px;padding:10px 14px;text-decoration:none;font:inherit;font-weight:700;cursor:pointer}.pack-actions a{background:#fff;color:#111}
.price-rules{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:24px}.price-rule{background:#fff;border:1px solid rgba(0,0,0,.14);padding:18px;border-radius:18px}.price-rule b{display:block;font-size:1.65rem}.price-rule span{font-size:.85rem;color:#555}.catalogue-cta{margin-top:20px;display:flex;gap:12px;align-items:center;flex-wrap:wrap}.catalogue-cta a{display:inline-flex;padding:13px 18px;border-radius:999px;background:#111;color:#fff;text-decoration:none;font-weight:800}.catalogue-cta small{max-width:520px;color:#555}.selection-field{display:grid;gap:8px}.selection-field textarea{width:100%;border:1px solid #bbb;border-radius:12px;padding:12px;font:inherit;resize:vertical}
.card[data-id^="PACK-"] .card-photo{background:#fbfaf7}.card[data-id^="PACK-"] .card-photo img{object-fit:contain;padding:10px}.card[data-id^="PACK-"] .brief{min-height:3.5em}
@media(max-width:800px){.sticker-pack-head{align-items:start;flex-direction:column}.price-rules{grid-template-columns:1fr 1fr}.pack-track{grid-auto-columns:min(86vw,360px)}}
@media(max-width:480px){.price-rules{grid-template-columns:1fr}.sticker-pack-hub{padding:54px 16px}}
.catalogue-main-link{display:inline-block;padding:14px 20px;margin:15px 0 18px;background:#111;color:white;border-radius:999px;font-weight:800;text-decoration:none}.price-rule del,.pack-prices del,.old-price{color:#827b77;font-size:.75em;font-weight:500;margin-right:7px}.pack-visual.holo-selected:after,.holo-card .card-photo:after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(115deg,transparent 28%,#fff8 46%,#b5f4ff77 52%,#ffe2f777 60%,transparent 75%);background-size:230% 100%;animation:shine 3.5s linear infinite}@keyframes shine{to{background-position:-230% 0}}@media(prefers-reduced-motion:reduce){.pack-visual.holo-selected:after,.holo-card .card-photo:after{animation:none}}
.magnet-carousel-controls{display:flex;justify-content:space-between;gap:10px;margin:9px 0}.magnet-carousel-controls button{border:1px solid #bbb;background:white;border-radius:99px;padding:5px 12px;cursor:pointer}.magnet-carousel-controls span{font-size:11px;align-self:center}.magnet-design{width:100%;padding:9px;margin:6px 0;border:1px solid #bbb;border-radius:7px}

.pack-prices{grid-template-columns:auto auto 1fr auto auto 1fr}.pack-finish select{padding:7px;border-radius:8px;border:1px solid #bbb}.selection-field input{width:100%;padding:12px;border:1px solid #bbb;border-radius:9px;font:inherit}

.detail-media.holo-selected{position:relative;overflow:hidden}.detail-media.holo-selected:after{content:'';position:absolute;inset:0;pointer-events:none;background:linear-gradient(110deg,transparent 28%,#fff7 46%,#a3eef377 53%,#fed9ff77 60%,transparent 75%);background-size:220% 100%;animation:shine 3.5s linear infinite}@media(prefers-reduced-motion:reduce){.detail-media.holo-selected:after{animation:none}}
/* Roomy price layout keeps both finishes readable on small screens. */
.pack-prices{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:14px 0}.pack-price-item{border:1px solid #e6e0db;border-radius:12px;padding:9px;display:flex;flex-wrap:wrap;gap:4px 7px;align-items:baseline;min-width:0}.pack-price-item b,.pack-price-item i{font-size:1.4rem;white-space:nowrap}.pack-price-item span{display:block;width:100%;white-space:normal;letter-spacing:.02em}.pack-price-item del{font-size:.9rem}.instagram-reel-track{display:flex;gap:14px;overflow-x:auto;max-width:100%;margin-top:18px;scroll-snap-type:x mandatory}.reel-card{flex:0 0 min(280px,78vw);background:#fff;border:1px solid #ddd;border-radius:16px;overflow:hidden;scroll-snap-align:start}.reel-head{padding:10px 12px;display:flex;justify-content:space-between}.reel-frame{aspect-ratio:9/16;background:linear-gradient(135deg,#261d35,#743b6f,#e5ad82);display:grid;place-items:center}.reel-frame button{border:1px solid #fff;background:#111b;color:white;border-radius:999px;padding:14px 17px;font-weight:800;cursor:pointer}.reel-frame iframe{width:100%;height:100%;border:0}.reel-card p,.reel-card a{display:block;margin:10px 12px}.reel-card a{color:#111;font-weight:700}
.pack-visual>img{object-fit:cover}.pack-visual .visual-note{position:absolute;left:12px;bottom:12px;background:#191616d9;color:#fff;padding:7px 10px;border-radius:8px;font-size:.68rem;max-width:calc(100% - 24px);line-height:1.35}
.pack-actions .share-pack{background:#fff;color:#111;border-color:#bbb}
.pack-visual .visual-note{bottom:66px;max-width:calc(100% - 24px)}.pack-image-controls{position:absolute;left:12px;right:12px;bottom:12px;display:flex;align-items:center;justify-content:space-between;gap:8px;background:#111e;color:#fff;border-radius:999px;padding:5px}.pack-image-controls button{border:0;background:#fff;color:#111;width:36px;height:36px;border-radius:50%;font-size:1.15rem;cursor:pointer}.pack-image-controls span{font-size:.78rem;font-weight:800}.pack-visual[data-index="0"]>img{object-fit:cover}.pack-visual:not([data-index="0"])>img{object-fit:contain;padding:25px;background:#f7f5f0}.pack-visual:has(img[src$="quality-card.svg"])>img{padding:0;object-fit:cover}
.design-carousel-head{display:flex;align-items:end;justify-content:space-between;gap:18px;margin:48px 0 15px}.design-carousel-head h3{font-size:clamp(1.75rem,3.3vw,3rem);margin:.1em 0}.design-carousel-head p{margin:.25em 0}.all-sticker-track{display:flex;gap:12px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:thin;padding:4px 2px 16px}.design-slide{flex:0 0 clamp(145px,16vw,205px);scroll-snap-align:start;background:#fff;border:1px solid #e4ddd3;border-radius:16px;overflow:hidden;text-decoration:none;color:#111;display:flex;flex-direction:column}.design-slide img{width:100%;aspect-ratio:1;object-fit:contain;padding:11px;background:#f7f5f0}.design-slide b,.design-slide small{margin:7px 11px 0}.design-slide small{color:#625e58;font-size:.75rem;margin-bottom:11px;line-height:1.35}.quality-slide img{padding:0;object-fit:cover}@media(max-width:600px){.design-carousel-head{align-items:start}.design-slide{flex-basis:155px}}
.instagram-reel-track:not(:empty){grid-column:1/-1;width:100%}.instagram-showcase:has(.instagram-reel-track:not(:empty)){align-items:start}

.catalogue-after-shop{display:flex;align-items:center;justify-content:space-between;gap:25px;background:#f8f2e8;border-top:1px solid #e5ddd2}.catalogue-after-shop h2{font-size:clamp(2rem,4vw,3.4rem);margin:.15em 0}.catalogue-after-shop p{max-width:530px}.catalogue-after-shop a{display:inline-flex;align-items:center;justify-content:center;padding:16px 22px;background:#111;color:#fff;border-radius:999px;text-decoration:none;font-weight:800;white-space:nowrap}@media(max-width:700px){.catalogue-after-shop{flex-direction:column;align-items:start}.catalogue-after-shop a{white-space:normal}}
.sheet-track .sheet-slide{flex-basis:clamp(215px,26vw,340px)}.sheet-track .sheet-slide img{aspect-ratio:3/4;object-fit:contain;background:#faf8f3;padding:12px}.sheet-track{padding-bottom:22px}
.catalogue-cta{display:flex;gap:10px;flex-wrap:wrap}.catalogue-cta a+a{background:#e5d2fa;color:#21162b}@media(max-width:700px){.catalogue-cta{width:100%}}
